<script setup lang="ts">
import { computed } from 'vue'; import { useRouter } from 'vue-router'; import PageHeader from '../components/PageHeader.vue'; import MetricCard from '../components/MetricCard.vue'; import RuntimeBanner from '../components/RuntimeBanner.vue'; import { useProjectStore } from '../stores/projectStore'; import { phaseLabel } from '../presentation/projectLabels'
const store=useProjectStore(), router=useRouter(); const project=computed(()=>store.project); const id=computed(()=>store.currentProjectId??''); const nextAction=computed(()=>store.pendingDecisionCount?{label:`处理 ${store.pendingDecisionCount} 个待决定事项`,to:`/projects/${id.value}/decisions`}:project.value?.phase==='PITCHING'?{label:'确认故事方向',to:`/projects/${id.value}/directions`}:project.value?.phase==='STORY_BLUEPRINT'?{label:'进入故事核心',to:`/projects/${id.value}/setup`}:{label:'进入创作中心',to:`/projects/${id.value}/production`})
const workspaces=[['市场与平台策略','market','市场机会、平台规则与卷间复核'],['故事方向','directions','立项、书级战略与故事承诺'],['故事核心','setup','确认主角、欲望与核心机制'],['开篇准备','opening','确认前三章承诺并建立第一章最小规划'],['项目助手','assistant','查询当前作品记录并在授权后执行修复'],['创作中心','production','生产链、审核与恢复'],['卷管理','volumes','按卷规划、生产与关闭'],['决策收件箱','decisions','统一处理需要人工裁决的事项'],['成品阅读','read','按卷懒加载正式章节'],['作品图谱','graph','人物、关系、伏笔与知识差'],['长篇健康','health','主线、角色、伏笔与重复风险'],['版本与变更记录','history','影响分析与正式历史'],['项目设置','settings','预算、平台、隐私与导出']]
</script>
<template><div v-if="project && store.overview" class="page"><PageHeader :title="project.title" :subtitle="project.subtitle"><button class="btn" @click="router.push('/projects')">返回作品库</button><button class="btn primary" @click="router.push(nextAction.to)">{{ nextAction.label }}</button></PageHeader><RuntimeBanner :state="project.runState" :reason="project.blockReason"/><div class="metric-grid section"><MetricCard label="整体进度" :value="`${project.progress}%`" :note="phaseLabel(project.phase)"/><MetricCard label="正式章节" :value="project.committedChapters" note="正文按章节查询，不常驻页面内存"/><MetricCard label="累计成本" :value="`¥${project.totalCost.toFixed(2)}`" :note="`总耗时 ${project.totalElapsed}`"/><MetricCard label="待处理决定" :value="store.pendingDecisionCount" :note="store.overview.healthSummary.label"/></div><section class="section"><div class="section-head"><div><h2>项目工作区</h2><div class="muted" style="font-size:12px">每个工作区只查询自己的投影，不加载整部作品。</div></div></div><div class="workspace-cards"><button v-for="w in workspaces" :key="w[1]" @click="router.push(`/projects/${id}/${w[1]}`)"><span>◇</span><strong>{{ w[0] }}</strong><small>{{ w[2] }}</small></button></div></section><section class="section overview-recent-grid"><div class="card pad"><div class="card-head"><div><h2 class="card-title">最近正式章节</h2><p class="card-subtitle">这里只是轻量目录摘要。</p></div></div><div v-if="store.overview.recentChapters.length" class="overview-chapters"><div v-for="c in store.overview.recentChapters" :key="c.id"><span>第 {{ c.number }} 章</span><strong>{{ c.title }}</strong><small>{{ c.wordCount.toLocaleString() }} 字 · {{ c.version }}</small></div></div><div v-else class="empty">尚未生成正式章节</div></div><div class="card pad"><div class="card-head"><div><h2 class="card-title">最近产物</h2><p class="card-subtitle">只展示最近摘要，不加载全部历史。</p></div></div><div class="artifact-list"><div v-for="a in store.overview.recentArtifacts" :key="a.id" class="artifact-row"><div><strong>{{ a.title }}</strong><div class="muted" style="font-size:11px">{{ a.version }}</div></div><span class="badge" :class="a.status==='official'?'success':'warning'">{{ a.status==='official'?'正式':'制作中' }}</span></div></div></div></section></div></template>
